#!/usr/bin/env python3
"""Assemble the decision page from receipt-checked, repository-native renders."""
import base64
import hashlib
import html
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent

def image(path, alt):
 p=HERE/path
 if p.suffix=='.png':
  receipt=json.loads(p.with_suffix('.json').read_text())
  assert hashlib.sha256(p.read_bytes()).hexdigest()==receipt['output'],p
 mime='image/svg+xml' if p.suffix=='.svg' else 'image/png'
 return '<img loading="lazy" alt="'+html.escape(alt)+'" src="data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()+'">'
def pair(directory, names, captions):
 return '<div class="pair">'+''.join('<figure>'+image(directory+'/renders/'+n+'.png',c)+'<figcaption>'+c+'</figcaption></figure>' for n,c in zip(names,captions))+'</div>'
page='''<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hauptstädte · Entwürfe zur Entscheidung</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#111b20;color:#e5e2d7;font:16px/1.55 system-ui,sans-serif}main{max-width:1600px;padding:28px;margin:auto}h1{font-size:30px}h2{margin-top:0;font-size:25px}h3{font-size:19px}p{max-width:1000px}a{color:#e5c282}nav{display:flex;gap:20px;flex-wrap:wrap;padding:16px 0 24px}section{padding:26px 0;border-top:1px solid #47524f;scroll-margin-top:10px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:12px 0}img{display:block;width:100%;height:auto;background:#182328;border-radius:5px}figcaption{padding:9px 0;color:#dbcead}.note{padding:12px 16px;background:#24332f;border-left:3px solid #c3a66f}.maps{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.maps figcaption{font-size:15px}summary{cursor:pointer;color:#e5c282;padding:10px 0}footer{font-size:14px;color:#b0b7b5;padding:25px 0}@media(max-width:850px){.pair,.maps{grid-template-columns:1fr}main{padding:16px}}
</style><main><h1>Hauptstädte · Entwürfe zur Entscheidung</h1><p>Vorhandene Spielgeometrie und Texturen, gerendert mit unserem Gebäude-Renderer. Alle Änderungen sind Vorschläge im Worktree <code>character-creation</code>. Die Spielgebäude und NPC-Standorte sind unverändert.</p><nav><a href="#throne">Thron</a><a href="#gate">Torbogen</a><a href="#tables">Tische</a><a href="#castle">Seitenwände</a><a href="#ridge">Dachfirst</a><a href="#registrar">Registrar</a></nav>
<section id="throne"><h2>1 · Thron absenken</h2><p>Die unterste bronzene Schicht entfällt. Sitzfläche: <strong>2 → 1 Block über dem Podest</strong>. Armlehnen: <strong>1½ → 1 Block über dem Sitz</strong>. Rücken und Ziersteine sinken mit ab; Grundfläche und Podest bleiben erhalten.</p><p>Die neutrale Figur ist 2,72 Blöcke hoch – die Höhe des Königs. Sie dient nur als Maßreferenz.</p>'''
page+=pair('throne',['before','after'],['Ist-Zustand','Vorschlag · tieferer Sitz und niedrigere Armlehnen'])
page+='''<p><a href="throne/index.html">Separate Thron-Vorschau</a> · <a href="throne/scenes.html">Interaktive 3D-Ansicht</a></p></section><section id="gate"><h2>2 · Diese Stufen sind gemeint</h2><p>Markiert sind die oberen inneren Ecken des Tordurchgangs. Die aktuelle Aussparung setzt sich als kleiner Kanal durch die Tiefe des Torhauses fort. Die gedrehte Variante öffnet die Stufe nach unten zum Durchgang.</p><p class="note">Bitte zuerst die markierte Stelle bestätigen. Betroffen sind die Kerntore von Highcourt, Dur Brannoc, Lethariel, Gor Drazhak und Nhal Veyr. Kezamba hat einen anderen Toraufbau.</p>'''
page+=pair('gates_roof',['gate-current','gate-proposal'],['Ist-Zustand · betroffene Stufen markiert','Vorschlag · umgedrehte Stufen'])
page+='''<details><summary>Tor im Zusammenhang ansehen</summary>'''+image('gates_roof/renders/gate-context.png','Aktuelles Tor mit markierter Fundstelle')+'''</details><p><a href="gates_roof/index.html">Tor- und Dachstudie</a></p></section><section id="tables"><h2>3 · Dünne Tischplatten mit passenden Beinen</h2><p>Der Registrar-Tisch ist aktuell 1½ Blöcke hoch. Bei den anderen Tischen liegen Platte und Pfosten nebeneinander, ohne sich zu berühren. Die vorhandene dünne Tischvariante ist <strong>1 Block hoch</strong>, hat eine <strong>⅛ Block dicke Platte</strong> und ein durchgehendes Mittelbein.</p><p>Vorschlag zunächst für die sechs Mining-Gilden. Zusammenhängende Einzeltische ersetzen die bisherigen Aufbauten; NPC-Positionen bleiben gleich. Bei Elfen und Untoten würde die derzeitige Steinplatte dabei durch Holz ersetzt.</p>'''
page+=pair('tables',['detail_before','detail_after'],['Ist-Zustand · hoher Tisch und schwebende Platte','Vorschlag · vorhandene dünne Holztische'])
page+='<details><summary>Im Gebäude mit Größenreferenzen ansehen</summary>'+pair('tables',['human_before','human_after'],['Human-Gildenhaus · vorher','Human-Gildenhaus · Vorschlag'])+'</details><p><a href="tables/index.html">Vergleich aller sechs Gildenhäuser</a> · <a href="tables/scenes.html">Interaktive 3D-Ansichten</a></p></section>'
page+='''<section id="castle"><h2>4 · Seitenwände als offene Säulenfelder</h2><p>Die schmalen Durchgänge führen hinter die Hallenwand. An den äußeren Stützen bleibt nur ein Block Platz. Der König passt mit seiner Kollisionsbreite von 0,96 Blöcken theoretisch hinein; ein zuverlässiger Verfolgungskampf ist damit noch nicht nachgewiesen.</p><p class="note">Meine Empfehlung: breite Öffnungen statt der unteren inneren Wand. Säulen mit den äußeren Stützen verbinden, damit dahinter keine engen Schlitze bleiben. Lampen sitzen wieder an den Säulen; die störenden Sitzbänke entfallen.</p>'''
page+=pair('castle',['current','pillars'],['Ist-Zustand · Seitendurchgang','Vorschlag A · offene Säulenfelder'])
page+='<details><summary>Alternative B: Durchgänge schließen</summary>'+image('castle/renders/closed.png','Alternative: geschlossene Seitendurchgänge')+'<p>Der kleinste Eingriff, aber ohne die offenere Halle. Die nicht mehr nutzbaren Durchgangspunkte müssten bei der Umsetzung ebenfalls entfernt werden.</p></details>'
page+='<details><summary>Grundrisse vergleichen</summary><div class="pair"><figure>'+image('castle/current.svg','Aktueller Grundriss')+'<figcaption>Ist-Zustand</figcaption></figure><figure>'+image('castle/pillars.svg','Vorgeschlagener Grundriss')+'<figcaption>Säulenfelder · grün markierte Geometrie</figcaption></figure></div><p>Geometrieschnitt; kein Wegfindungstest. Die offene Variante vermeidet die engen Seitengänge durch den Gebäudeaufbau.</p></details><p><a href="castle/scenes.html">Interaktive Schloss-Varianten</a></p></section>'
page+='''<section id="ridge"><h2>5 · Dachfirst einen halben Block absenken</h2><p>Die mittlere Firstgruppe schwebt tatsächlich ½ Block über den benachbarten Dachflächen. Mit den vorhandenen Block- und Plattenformen lässt sich dieselbe Firsthöhe beibehalten und die gesamte Gruppe um ½ Block absenken. Alle sechs Schlösser teilen diesen Aufbau.</p>'''
page+=pair('gates_roof',['ridge-current','ridge-proposal'],['Ist-Zustand · Lücke im Querschnitt','Vorschlag · First um ½ Block abgesenkt'])
page+='''</section><section id="registrar"><h2>6 · Registrar draußen – aber wo?</h2><p>Ein gut sichtbarer Anmeldeplatz im Hauptstadt-Kern wäre leichter zu finden. Neben dem Schloss passt er thematisch gut; für einen kurzen Weg vom Waystone ist das aber nicht in jeder Hauptstadt ideal.</p><p><strong>W</strong> = aktueller Waystone · <strong>E</strong> = aktueller Schlosseingang · <strong>R</strong> = möglicher Außenstandort neben dem Schloss. Die gestrichelte Verbindung zeigt nur die Luftlinie, keinen geprüften Laufweg. Die Gildenposition außerhalb des Kerns hängt vom Welt-Seed ab.</p><div class="maps">'''
D=json.loads((HERE/'castle/registrar-candidates.json').read_text())
for city,title in [('highcourt','Highcourt'),('dur_brannoc','Dur Brannoc'),('lethariel','Lethariel'),('gor_drazhak','Gor Drazhak'),('nhal_veyr','Nhal Veyr'),('kezamba','Kezamba')]:
 distance=str(D[city]['straight_distance_waystone_to_candidate']).replace('.',',')
 page+='<figure>'+image('castle/'+city+'-map.svg',title+' · tatsächlicher Hauptstadt-Kern')+'<figcaption><strong>'+title+'</strong> · '+distance+' Blöcke Luftlinie vom Waystone zum Vorschlag</figcaption></figure>'
page+='''</div><p class="note">Wenn die schnelle Erreichbarkeit Vorrang hat, empfehle ich den Registrar am Zugang zum Waystone-Platz – außerhalb der freien Ankunftsfläche. Besonders in Kezamba liegt das Schloss weit davon entfernt. Wenn dir die Nähe zum König wichtiger ist, zeigen die R-Markierungen konkrete freie Standorte am Schloss.</p><p>Für Gor Drazhak liegt der Vorschlag auf der westlichen Seite, weil östlich bereits die erhöhte Kampfplattform steht. Die NPC-Zuweisung und Expeditionsfunktionen bleiben bis zur Standortentscheidung unverändert.</p></section><footer>Entwurfsrunde · 10. November 2026 · Gemeinsamer Spiel-Renderer, vorhandene Medien. Helle Geometriestudien, keine nativen Client-Aufnahmen. Kein Merge, Push oder Eingriff in Claudes Arbeit auf main. Änderungsquellen und Messdaten liegen bei den einzelnen Studien.</footer></main></html>'''
(HERE/'index.html').write_text(page)
print('Built',HERE/'index.html',len(page),'characters')
